function openPanel(canvas,overlay,focus){overlay.dataset.closing='false';canvas.append(overlay);layers(canvas);animate(overlay,[{opacity:0,transform:'scale(.97) translateY(6px)'},{opacity:1,transform:'scale(1) translateY(0)'}]);focus.focus();}
function closePanel(canvas,overlay,trigger){if(overlay.dataset.closing==='true')return;overlay.dataset.closing='true';const motion=animate(overlay,[{opacity:1,transform:'scale(1)'},{opacity:0,transform:'scale(.985)'}],140);const finish=()=>{overlay.remove();layers(canvas);if(trigger.isConnected&&!trigger.inert)trigger.focus();};if(motion)void motion.finished.then(finish,finish);else finish();}
function list(items,ordered=false){const node=el(ordered?'ol':'ul');items.forEach(text=>node.append(el('li','',text)));return node;}
function download(name,mime,data){const a=el('a'),binary=mime==='base64'||mime.startsWith('base64:');a.download=name;a.href=binary?`data:${mime==='base64'?'application/zip':mime.slice(7)};base64,${data}`:URL.createObjectURL(new Blob([data],{type:mime}));a.click();if(!binary)URL.revokeObjectURL(a.href);}
function copy(text,container,status,onCopied=()=>{}){
  const fallback=()=>{const field=el('textarea');field.value=text;field.readOnly=true;field.setAttribute('aria-label','Text to copy');container.append(field);field.focus();field.select();let ok=false;try{ok=document.execCommand('copy');}catch{}if(ok){field.remove();status.textContent='Copied';onCopied();}else{status.textContent='Select the text and press Ctrl+C or Command+C.';field.style.cssText='position:absolute;inset:50px;z-index:20;font:22px Arial;background:white;padding:20px';field.onblur=()=>field.remove();}};
  if(navigator.clipboard?.writeText)navigator.clipboard.writeText(text).then(()=>{status.textContent='Copied';onCopied();},fallback);else fallback();
}
function trapDialog(overlay,close){overlay.addEventListener('keydown',event=>{event.stopPropagation();if(event.key==='Escape'){event.preventDefault();close.click();}if(event.key==='Tab'){const nodes=[...overlay.querySelectorAll('button,a,textarea,input,select,[tabindex="0"]')].filter(n=>!n.disabled&&n.getBoundingClientRect().width>0),first=nodes[0],last=nodes[nodes.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}});}
function showRiskCase(canvas,trigger,example){
 if(example.kind==='chat'){showRiskChat(canvas,trigger,example);return;}
 if(example.kind==='scene'){showRiskScene(canvas,trigger,example);return;}
 const panel=el('section','topicOverlay aba-panel riskCase');panel.setAttribute('role','dialog');panel.setAttribute('aria-modal','true');panel.setAttribute('aria-label',example.title);
 const header=el('header','riskCaseHeading'),title=el('h2','',example.title),actions=el('div','riskCaseActions'),source=el('a','','Source'),close=button('Close',()=>closePanel(canvas,panel,trigger));source.href=example.source;source.target='_blank';source.rel='noopener noreferrer';close.setAttribute('aria-label','Close real-world case');actions.append(source,close);header.append(title,actions);
 const steps=el('div','riskCaseSteps');for(const [index,[label,text]]of example.steps.entries()){const card=el('article','riskCaseStep');card.append(el('strong','riskCaseNumber',String(index+1).padStart(2,'0')),el('h3','',label),el('p','',text));steps.append(card);}panel.append(header,steps);trapDialog(panel,close);openPanel(canvas,panel,close);for(const [index,card]of [...steps.children].entries())animate(card,[{opacity:0,transform:'translateY(16px)'},{opacity:1,transform:'translateY(0)'}],280+index*80);
}
function renderGASDefinition(s,body,canvas){
 const layout=el('section','gasDefinition'),text=el('p','promptDefinitionText',s.text),trigger=button('',()=>{
  const ecosystem=s.ecosystem,panel=el('section','topicOverlay aba-panel googleEcosystem'),header=el('header','ecosystemHeading'),close=button('Close',()=>closePanel(canvas,panel,trigger));panel.setAttribute('role','dialog');panel.setAttribute('aria-modal','true');panel.setAttribute('aria-label',ecosystem.title);close.setAttribute('aria-label','Close Google ecosystem');header.append(el('h2','',ecosystem.title),close);
  const grid=el('div','ecosystemGrid'),detail=el('div','ecosystemDetail'),name=el('h3'),description=el('p'),state=stateFor(ecosystem);grid.setAttribute('aria-label','Google tools');detail.setAttribute('role','status');detail.setAttribute('aria-live','polite');detail.append(name,description);
  const buttons=ecosystem.tools.map((tool,index)=>{const control=button('',()=>select(index));control.className='ecosystemTool';control.setAttribute('aria-label',tool.name);control.setAttribute('aria-description',tool.function);if(tool.icons){const suite=el('span','ecosystemSuite');for(const mark of tool.icons)suite.append(icon(mark));control.append(suite);}else control.append(icon(tool.icon));control.addEventListener('pointerenter',()=>select(index));control.addEventListener('focus',()=>select(index));grid.append(control);return control;});
  function select(index){state.selected=index;name.textContent=ecosystem.tools[index].name;description.textContent=ecosystem.tools[index].function;buttons.forEach((node,i)=>node.setAttribute('aria-pressed',String(i===index)));}
  select(state.selected||0);panel.append(header,grid,detail);trapDialog(panel,close);openPanel(canvas,panel,close);
 });trigger.className='ecosystemLauncher';trigger.setAttribute('aria-haspopup','dialog');const marks=el('span','ecosystemLauncherIcons');for(const mark of ['gmail','calendar','drive'])marks.append(icon(mark));trigger.append(marks,el('strong','',s.ecosystem.title));layout.append(text,trigger);body.append(layout);
}
function showRiskChat(canvas,trigger,example){
 const state=stateFor(example),requestId=window.eiuLessonRequestId,panel=el('section','topicOverlay aba-panel riskCase riskChat');let ready=!requestId,epoch='';panel.setAttribute('role','dialog');panel.setAttribute('aria-modal','true');panel.setAttribute('aria-label',example.title);
 const header=el('header','riskCaseHeading'),title=el('h2','chatGPTTitle'),actions=el('div','riskCaseActions'),close=button('\u00d7',()=>{cleanup();closePanel(canvas,panel,trigger);});title.append(icon('chatgpt'),document.createTextNode('ChatGPT'));close.setAttribute('aria-label','Close chatbot example');actions.append(close);header.append(title,actions);
 const log=el('div','riskChatLog');log.tabIndex=0;log.setAttribute('role','log');log.setAttribute('aria-label','Conversation. Click or press Space for the next message.');log.setAttribute('aria-live','polite');log.setAttribute('aria-relevant','additions');
 const composer=el('div','riskChatComposer');composer.setAttribute('aria-hidden','true');composer.append(el('span','chatComposerPlus','+'),el('span','','Ask anything'),el('span','chatComposerSend','\u2191'));
 function append(message){const bubble=el('article','riskChatMessage '+(message.role==='User'?'riskChatUser':'riskChatAI')),copy=el('div','riskChatCopy');bubble.setAttribute('aria-label',message.role+' message');if(message.attachment){const attachment=el('div','riskChatAttachment');attachment.setAttribute('role','img');attachment.setAttribute('aria-label','Mushroom photo attachment');attachment.innerHTML='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 88 64" aria-hidden="true"><rect width="88" height="64" rx="10" fill="#e7e9db"/><path d="M36 36h16l4 22H32z" fill="#f7f1d8" stroke="#8b795d" stroke-width="2"/><path d="M13 35C14 4 74 4 75 35Q44 47 13 35Z" fill="#a17b56" stroke="#6e543d" stroke-width="2"/><path d="M21 34q23 10 46 0" fill="none" stroke="#e8d5b9" stroke-width="3"/></svg>';bubble.append(attachment);}if(message.role==='AI')bubble.append(icon('chatgpt'));copy.append(el('p','',message.text));bubble.append(copy);log.append(bubble);return bubble;}
 function update(){panel.dataset.messageCount=String(state.messageCount||0);panel.dataset.chatReady=String(ready);panel.dataset.complete=String((state.messageCount||0)>=example.messages.length);}
 function paint(){log.replaceChildren();for(const message of example.messages.slice(0,state.messageCount||0))append(message);if(!state.messageCount)log.append(el('div','riskChatWelcome','What can I help with?'));update();log.scrollTop=log.scrollHeight;}
 function reveal(){if(!ready||window.eiuSectionEnded||(state.messageCount||0)>=example.messages.length)return;if(!state.messageCount)log.replaceChildren();const bubble=append(example.messages[state.messageCount||0]);state.messageCount=(state.messageCount||0)+1;update();if(requestId&&epoch)window.parent.postMessage({type:'eiu-risk-chat-save',requestId,epoch,count:state.messageCount},'*');animate(bubble,[{opacity:0,transform:'translateY(14px)'},{opacity:1,transform:'translateY(0)'}],260);log.scrollTop=log.scrollHeight;}
 function receive(event){const message=event.data;if(event.source!==window.parent||message?.type!=='eiu-risk-chat-state'||message.requestId!==requestId||(message.exampleId!==undefined&&message.exampleId!=='chat')||!Number.isInteger(message.count)||message.count<0||message.count>example.messages.length||typeof message.epoch!=='string'||window.eiuSectionEnded)return;state.messageCount=message.count;epoch=message.epoch;ready=true;paint();}
 function cleanup(){window.removeEventListener('message',receive);window.removeEventListener('pagehide',cleanup);}
 panel.addEventListener('click',event=>{if(!event.target.closest('button,a')&&!window.getSelection()?.toString())reveal();});log.addEventListener('keydown',event=>{if(event.key===' '||event.key==='Enter'){event.preventDefault();reveal();}});panel.append(header,log,composer);paint();trapDialog(panel,close);openPanel(canvas,panel,close);if(requestId){window.addEventListener('message',receive);window.addEventListener('pagehide',cleanup,{once:true});window.parent.postMessage({type:'eiu-risk-chat-load',requestId},'*');}
}
