 function fly(target,source){const a=source.getBoundingClientRect(),b=target.getBoundingClientRect(),scale=canvas.getBoundingClientRect().width/1136.64;animate(target,[{opacity:.3,transform:'translate('+((a.left-b.left)/scale)+'px,'+((a.top-b.top)/scale)+'px) scale(.65)'},{opacity:1,transform:'translate(0,0) scale(1)'}],620);}
