 const content=el('div','historyContent'),timeline=el('ol','historyEvents');
 for(const event of s.events){const row=el('li'),copy=el('div'),title=el('h3'),text=el('p');title.textContent=event.title;text.textContent=event.text;copy.append(title,text);const date=historyLink(event.date,event.url,'historyEventDate');date.setAttribute('aria-label',event.date+': '+event.title+' - official source');row.append(date,copy);timeline.append(row);}
 const market=el('section','historyMarket'),title=historyLink(s.marketTitle,s.marketUrl),text=el('p');text.textContent=s.marketText;market.append(title,text);content.append(timeline,market);layout.append(identity,content);body.append(layout);
