 models.setAttribute('aria-label','AI model');plugins.setAttribute('aria-label','Plugins');models.append(el('h1','','AI model'),modelStage);plugins.append(el('h1','','Plugins'),el('p','aiPluginIntro',s.items[1].content.intro),pluginStage);
