  trigger.className='floatingPlugin';trigger.dataset.slot=String(index);trigger.setAttribute('aria-label',platform.name+' integrations');trigger.setAttribute('aria-haspopup','dialog');const header=el('span','floatingPluginHeading'),name=el('strong'),term=el('span','floatingPluginTerm'),examples=el('span','floatingPluginExamples');name.textContent=platform.name;term.textContent=platform.term;for(const [i,[label]] of platform.examples.entries()){const chip=el('span','pluginChip'),text=el('span');text.textContent=label.replace('Google ','').replace(' connector','').replace(' plugin','');chip.append(icon(platform.exampleIcons[i]),text);examples.append(chip);}header.append(icon(platform.icon),name);trigger.append(header,term,examples);pluginStage.append(trigger);
