function renderAnnotatedPrompt(s,body){
 const root=el('section','annotatedPrompt samplePrompt'),actions=el('div','annotationActions'),board=el('div','samplePromptBoard'),state=stateFor(s);let revealed=Boolean(state.revealed);
 const sync=()=>{state.revealed=revealed;root.dataset.revealed=String(revealed);reveal.setAttribute('aria-pressed',String(revealed));reveal.textContent=revealed?'Hide components':'Identify components';};
 const reveal=button('Identify components',()=>{revealed=!revealed;sync();});sync();actions.append(reveal);
 board.append(el('strong','samplePromptLabel','Prompt:'));
 for(const paragraph of s.paragraphs){const p=el('p',paragraph.className);for(const [text,bold] of paragraph.runs){if(bold){const strong=el('strong');strong.textContent=text;p.append(strong);}else p.append(document.createTextNode(text));}board.append(p);}
 const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.classList.add('samplePromptArrows');svg.setAttribute('viewBox','0 0 1088 360');svg.setAttribute('aria-hidden','true');svg.innerHTML='<defs><marker id="sample-prompt-arrow" viewBox="0 0 6 6" refX="5" refY="3" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M0 0L6 3L0 6Z" fill="#17324a"/></marker></defs>';
 for(const annotation of s.annotations){const tag=el('span','componentLabel sampleComponentLabel');tag.textContent=annotation.component;tag.style.left=annotation.x+'px';tag.style.top=annotation.y+'px';board.append(tag);const line=document.createElementNS(svg.namespaceURI,'line');const [x1,y1,x2,y2]=annotation.line;for(const [name,value] of Object.entries({x1,y1,x2,y2,stroke:'#17324a','stroke-width':1.3,'marker-end':'url(#sample-prompt-arrow)'}))line.setAttribute(name,String(value));svg.append(line);}
 const tone=el('span','sampleTone');tone.textContent=s.tone;board.append(tone,svg);root.append(actions,board);body.append(root);
}
function demoLink(label,url){const a=historyLink('',url,'leaveDemo');a.append(icon('apps-script'),document.createTextNode(label));return a;}
function renderLeaveComparison(s,body){
 const root=el('section','leaveComparison'),bad=el('section','badPromptPanel'),good=el('section','goodPromptPanel'),badTitle=el('h2'),goodTitle=el('h2'),badText=el('p','badPromptText'),stage=el('section','goodPromptStage'),nav=el('nav','goodPromptNav');badTitle.textContent='Bad prompt';goodTitle.textContent='Good prompt';badText.textContent=s.bad;bad.append(badTitle,badText,demoLink('Open bad-prompt app',s.badUrl));
 const state=stateFor(s);let index=state.index||0;const previous=button('Previous part',()=>{index=Math.max(0,index-1);update();}),next=button('Next part',()=>{index=Math.min(s.pages.length-1,index+1);update();}),position=el('span','promptPartCount');nav.setAttribute('aria-label','Good prompt parts');nav.append(previous,position,next);
 function update(){state.index=index;const page=s.pages[index],title=el('h3');title.textContent=page.title;stage.replaceChildren(title);for(const text of page.paragraphs){const p=el('p');p.textContent=text;stage.append(p);}previous.disabled=index===0;next.disabled=index===s.pages.length-1;position.textContent=(index+1)+' / '+s.pages.length;}
 good.append(goodTitle,stage,nav,demoLink('Open good-prompt app',s.goodUrl));update();root.append(bad,good);body.append(root);
}
function createCaseIcon(name){
 const paths={game:'M7 7h10c2 0 3 2 3.5 4l1 6c.3 2-1.5 3-3 1l-3-3h-7l-3 3c-1.5 2-3.3 1-3-1l1-6C4 9 5 7 7 7ZM6 11h4m-2-2v4m7-2h.01m3 2h.01',document:'M7 3h8l4 4v14H5V3h2m8 0v5h5M8 12h8M8 16h6',idea:'M9 18h6m-5 3h4M8 14a7 7 0 1 1 8 0l-1 3H9l-1-3',check:'M4 12l5 5L20 5M4 21h16',mail:'M3 5h18v14H3ZM3 5l9 8 9-8',quiz:'M5 3h14v18H5ZM8 8h1m3 0h4M8 13h1m3 0h4M8 18h1m3 0h4',code:'M8 6l-6 6 6 6m8-12 6 6-6 6M14 3l-4 18',chart:'M3 3v18h19M7 17v-5m5 5V7m5 10V4',travel:'M3 12l18-8-7 18-3-8-8-2Zm8 2 10-10',fitness:'M3 7v10m3-13v16m12-16v16m3-13v10M6 12h12',meal:'M5 3v6m4-6v6M3 6h8v4H3ZM7 10v11M17 3v18m0-18c5 3 5 8 0 10',reflection:'M3 4h18v13H10l-5 4v-4H3ZM7 9h10M7 13h7',learn:'M2 7l10-4 10 4-10 4-10-4Zm4 2v8c4 3 8 3 12 0V9m4-2v10'};
 const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 24 24');svg.setAttribute('fill','none');svg.setAttribute('stroke','currentColor');svg.setAttribute('stroke-width','1.6');svg.setAttribute('stroke-linecap','round');svg.setAttribute('stroke-linejoin','round');svg.setAttribute('aria-hidden','true');svg.classList.add('useCaseIcon');const path=document.createElementNS(svg.namespaceURI,'path');path.setAttribute('d',paths[name]);svg.append(path);return svg;
}
