function chart(rows,max=100){const root=el('div','chart');for(const[label,value,mark]of rows){const row=el('div','barRow'),name=el('span','barName'),track=el('div','track'),bar=el('div','bar');name.textContent=label;if(mark)name.prepend(icon(mark));bar.style.width=`${100*value/max}%`;track.setAttribute('aria-hidden','true');track.append(bar);row.append(name,track,el('strong','',`${value}%`));root.append(row);}const axis=el('div','axis');axis.append(el('span','','0%'),el('span','','50%'),el('span','','100%'));root.append(axis);return root;}
