 const root=el('section','evidence'),toolbar=el('div','evidenceToolbar'),nav=el('nav','evidenceTabs'),plot=el('section','evidencePlot'),state=stateFor(s),panels=new Map();let index=state.view||0;
 nav.setAttribute('aria-label','Data perspectives');
