function renderBody(s,body,canvas){
  if(s.kind==='skill-demo'){
   const root=el('section','skillDemo'),cards=el('div','skillDemoCards');root.append(el('p','skillDemoIntro',s.intro));s.features.forEach(([title,text],i)=>{const card=el('section','skillDemoCard');card.append(el('span','skillDemoNumber',String(i+1).padStart(2,'0')),el('h2','',title),el('p','',text));cards.append(card);});
   const asset=course.skillDemoFiles[s.download],save=button('Download SKILL.md',()=>download(asset.name,'base64:'+asset.mime,asset.data));save.className='skillDemoDownload';root.append(cards,save);body.append(root);return;
  }
  if(s.kind==='skill-setup'){const root=el('section','skillSetup'),steps=el('ol','skillSetupSteps');s.steps.forEach((text,i)=>{const step=el('li','skillSetupStep');step.append(el('span','skillStepNumber',String(i+1)),el('p','',text));steps.append(step);});root.append(steps);body.append(root);return;}
  if(s.kind==='try-code'){
   const root=el('section','tryCode'),grid=el('div','tryCodeGrid'),footer=el('div','tryCodeFooter'),status=el('p','tryCopyStatus'),state=stateFor(s),files=s.fileSet==='sales-dashboard'?course.salesDashboardFiles:course.tryFiles;grid.dataset.count=String(s.files.length);state.copiedFiles=state.copiedFiles||[];status.setAttribute('role','status');status.setAttribute('aria-live','polite');
   for(const name of s.files){
    const file=button('',()=>{state.copiedFiles=state.copiedFiles.filter(f=>f!==name);file.dataset.copied='false';copy(files[name],root,status,()=>{if(!state.copiedFiles.includes(name))state.copiedFiles.push(name);file.dataset.copied='true';status.textContent=name+' copied';file.focus();});});
    file.className='tryCodeFile';file.dataset.copied=String(state.copiedFiles.includes(name));file.setAttribute('aria-label','Copy '+name);
    const mark=el('span','tryFileMark','{ }'),check=el('span','tryCopiedMark','\u2713');mark.setAttribute('aria-hidden','true');check.setAttribute('aria-hidden','true');file.append(mark,el('strong','',name),check);grid.append(file);
   }
   const resources=el('div','tryResources');if(s.download){const asset=course.salesData,save=button('Download Sale data (.xlsx)',()=>download(asset.name,'base64:'+asset.mime,asset.data));save.className='tryEditorLink salesDataDownload';save.prepend(icon('sheets'));resources.append(save);}if(s.url){const link=el('a','tryEditorLink');link.textContent='Google Apps Script';link.prepend(icon('apps-script'));link.href=s.url;link.target='_blank';link.rel='noopener noreferrer';resources.append(link);}footer.append(resources,status);
   if(s.limitations){root.classList.add('salesTry');const stage=el('div','salesTryStage');let panel;const help=button('',()=>{if(!panel){panel=el('section','topicOverlay aba-panel');panel.setAttribute('role','dialog');panel.setAttribute('aria-modal','true');panel.setAttribute('aria-label',s.limitations.title);const close=button('\u00d7',()=>closePanel(canvas,panel,help));close.className='topicClose';close.setAttribute('aria-label','Close topic');pageContent(s.limitations,panel,canvas,close);trapDialog(panel,close);}openPanel(canvas,panel,panel.querySelector('.topicClose'));});help.className='salesLimitTrigger';help.setAttribute('aria-label','What are the limitations?');help.setAttribute('aria-haspopup','dialog');const mark=el('span','salesLimitMark','?');mark.setAttribute('aria-hidden','true');help.append(mark);stage.append(grid,help);root.append(stage,footer);}else root.append(grid,footer);body.append(root);return;
  }
  if(s.kind==='gas-flow'){
   const root=el('section','gasFlow'),steps=el('ol','gasFlowSteps');
   s.steps.forEach(([title,text],i)=>{const item=el('li','gasFlowStep'),number=el('span','gasFlowNumber',String(i+1)),copy=el('div');copy.append(el('h2','',title),el('p','',text));item.append(number,copy);steps.append(item);});
   root.append(steps);body.append(root);return;
  }
  if(s.kind==='spending'){renderSpending(s,body,canvas);return;}
  if(s.kind==='evidence'){renderEvidence(s,body,canvas);return;}
  if(s.kind==='ai-tool'){renderAITool(s,body);return;}
  if(s.kind==='hub')renderHub(s,body,canvas);
  else if(s.kind==='split-overview')renderSplitOverview(s,body,canvas);
  else if(s.kind==='history')renderHistory(s,body,canvas);
  else if(s.kind==='plugins')renderPlugins(s,body);
  else if(s.kind==='use-cases')renderUseCases(s,body);
  else if(s.kind==='ai-caution')renderCaution(s,body);
  else if(s.kind==='annotated-prompt')renderAnnotatedPrompt(s,body);
  else if(s.kind==='leave-compare')renderLeaveComparison(s,body);
  else if(s.kind==='prompt-definition'){if(s.ecosystem)renderGASDefinition(s,body,canvas);else{const text=el('p','promptDefinitionText');text.textContent=s.text;body.append(text);}}
  else if(s.kind==='history-detail')renderHistoryDetail(s,body);
  else if(s.kind==='cover'){const cover=el('div','cover'),art=el('div','coverArt');art.innerHTML=course.coverArt;cover.append(art,el('h1','',s.title));const actions=el('div','actions'),objectives=button('Learning objectives',()=>showObjectives(canvas,objectives));actions.append(objectives);cover.append(actions);body.append(cover);}
  else if(s.kind==='showcase'){body.dataset.eiuShowcase='true';if(s.practice){const brief=el('section','practiceBrief'),steps=list(s.practice.steps,true);steps.className='practiceBriefSteps';brief.append(el('p','practiceBriefGoal',s.lead),steps,el('p','practiceBriefOnline','Open this slide in Learning to share your link or image and view the class board.'));body.append(brief);}}
}
function render(s){const root=document.createElement('eiu-aba-slide');root.className='slide aba-slide';root.dataset.eiuTemplate='system';root.dataset.mis311Frame='true';root.style.backgroundImage=`url(${JSON.stringify(course.frame)})`;root.setAttribute('aria-label',s.title);
  const content=el('div','aba-content');content.dataset.mis311Content='true';const canvas=el('main','aba-canvas');canvas.dataset.offlineCanvas='true';content.append(canvas);root.append(content);pageContent(s,canvas,canvas);const number=el('span','aba-page',String(s.number));number.dataset.mis311Page='true';root.append(number);return root;
}
exports.default = course.slides.map(s => () => render(s));
